#[path="support/packed_concat_masked.rs"] mod packed;
use binius_frontend::CircuitBuilder;
use binius_circuits::fixed_byte_vec::ByteVec;
use binius_core::word::Word;
fn main(){for cap in [129usize,513]{let width=cap.div_ceil(8);let b=CircuitBuilder::new();let ins:Vec<_>=(0..2+2*width).map(|_|b.add_inout()).collect();let a=ByteVec::new_with_len_range(ins[2..2+width].to_vec(),ins[0],0..=cap);let c=ByteVec::new_with_len_range(ins[2+width..].to_vec(),ins[1],0..=cap);let out=packed::concat(&b,&[a,c]);let count=out.data.len();let expected:Vec<_>=(0..count+1).map(|_|b.add_inout()).collect();b.assert_eq("length",out.len_bytes,expected[0]);for i in 0..count{b.assert_eq(format!("word-{i}"),out.data[i],expected[1+i]);}let circuit=b.build();let(mut checked,mut mutants)=(0,0);let lens:Vec<_>=[0,1,7,8,9,63,64,65,127,128,129,255,256,257,511,512,513].into_iter().filter(|&n|n<=cap).collect();
 for &a in &lens{for &c in &lens{let left:Vec<u8>=(0..width*8).map(|i|(i*3+1) as u8).collect();let right:Vec<u8>=(0..width*8).map(|i|(i*5+7) as u8).collect();let mut result=left[..a].to_vec();result.extend_from_slice(&right[..c]);result.resize(count*8,0);let words:Vec<u64>=vec![a as u64,c as u64].into_iter().chain(left.chunks_exact(8).chain(right.chunks_exact(8)).map(|x|u64::from_le_bytes(x.try_into().unwrap()))).chain(core::iter::once((a+c) as u64)).chain(result.chunks_exact(8).map(|x|u64::from_le_bytes(x.try_into().unwrap()))).collect();
 for change in core::iter::once(None).chain((ins.len()..words.len()).map(Some)){let mut w=circuit.new_witness_filler();for(i,wire)in ins.iter().chain(expected.iter()).enumerate(){w[*wire]=Word(words[i]^u64::from(change==Some(i)));}assert_eq!(circuit.populate_wire_witness(&mut w).is_ok(),change.is_none(),"cap{cap} lengths{a}/{c} mutation{change:?}");if change.is_none(){checked+=1}else{mutants+=1}}
 }}println!("PACKED_WIDE cap={cap} cases={checked} rejected_mutations={mutants} dirty_suffixes=true");}}
